/* Agenda: calendario, citas y tareas */
#include "z.h"
typedef struct { int y, m, d, done; char t[6], txt[120]; } it_t;
static zwin *W; static it_t *L; static int n; static int Y, M, D, tY, tM, tD, sel = -1; static char file[200];
static int dim(int y, int m) { static const u8 d[] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}; return m == 2 && (y % 4 == 0 && (y % 100 || y % 400 == 0)) ? 29 : d[m - 1]; }
static int dow(int y, int m, int d) { static const u8 t[] = {0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4}; if (m < 3) y--; return (y + y / 4 - y / 100 + y / 400 + t[m - 1] + d + 6) % 7; }
static const char *MN[] = {"Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio", "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"};
static void save(void) { sb_t b = {0}; sb_s(&b, ""); for (int i = 0; i < n; i++) { it_t *e = &L[i]; if (e->y) sb_f(&b, "C|%04d-%02d-%02d|%s|%s\n", e->y, e->m, e->d, e->t, e->txt); else sb_f(&b, "T|%d|%s\n", e->done, e->txt); } int r = z_writefile(file, b.p, b.n); free(b.p); char m[60]; snprintf(m, 60, "[prueba] agenda guardo: %s", r ? z_errstr(r) : "OK"); z_log(m); }
static void load(void) { char *d = z_readfile(file, 0); n = 0; if (!d) return; char *p = d; while (*p && n < 2000) { char *e = strchr(p, '\n'); if (e) *e = 0; it_t *i = &L[n]; memset(i, 0, sizeof *i); if (p[0] == 'C' && strlen(p) > 14) { i->y = atoi(p + 2); i->m = atoi(p + 7); i->d = atoi(p + 10); strncpy0(i->t, p + 13, 6); char *x = strchr(p + 13, '|'); if (x) { strncpy0(i->txt, x + 1, 120); n++; } } else if (p[0] == 'T') { i->done = p[2] == '1'; strncpy0(i->txt, p + 4, 120); n++; } if (!e) break; p = e + 1; } free(d); }
static int cmp_(const void *a, const void *b) { return strcmp(((it_t *)a)->t, ((it_t *)b)->t); }
#define CX 16
#define CY 56
#define CW 62
#define CH 54
static int vis[64], nv;
static void draw(void) {
    g_clear(W, UI_WHITE); g_rect(W, 0, 0, W->w, 44, UI_ACC); ui_button(W, 12, 9, 34, 26, "<", 0); ui_button(W, 50, 9, 34, 26, ">", 0); ui_button(W, 90, 9, 60, 26, "Hoy", 0); char b[160]; snprintf(b, 160, "%s %d", _(MN[M - 1]), Y); g_text2(W, 170, 6, b, 0xFFFFFF, 2); ui_button(W, W->w - 110, 9, 98, 26, "Imprimir", 0); static const char *DN[] = {"Lun", "Mar", "Mie", "Jue", "Vie", "Sab", "Dom"}; for (int i = 0; i < 7; i++) g_text(W, CX + i * CW + 18, CY - 8 + 0, DN[i], UI_MUTED); int f = dow(Y, M, 1), dn = dim(Y, M); for (int d = 1; d <= dn; d++) { int c = f + d - 1, X = CX + (c % 7) * CW, Yy = CY + 12 + (c / 7) * CH; if (d == D) g_rect(W, X, Yy, CW - 2, CH - 2, UI_ACC2); g_frame(W, X, Yy, CW - 2, CH - 2, UI_LINE); snprintf(b, 8, "%d", d); int today = d == tD && M == tM && Y == tY; if (today) g_textb(W, X + 5, Yy + 4, b, 0xDC2626); else g_text(W, X + 5, Yy + 4, b, UI_TEXT); int k = 0; for (int i = 0; i < n; i++) if (L[i].y == Y && L[i].m == M && L[i].d == d) k++; for (int i = 0; i < MIN(k, 6); i++) g_rect(W, X + 6 + i * 8, Yy + 36, 6, 6, UI_ACC); }
    int X = CX + 7 * CW + 16, w = W->w - X - 12, y = 56; zs_area(W, X, 50, W->w - X, W->h - 50, 0); if (TH.lang) snprintf(b, 160, "%s %d", _(MN[M - 1]), D); else snprintf(b, 160, "%d de %s", D, MN[M - 1]); g_textb(W, X, y, b, UI_TEXT); ui_button(W, W->w - 96, y - 4, 84, 24, "+ Cita", 0); y += 26; nv = 0; it_t tmp[32]; int idx[32], c = 0; for (int i = 0; i < n && c < 32; i++) if (L[i].y == Y && L[i].m == M && L[i].d == D) { tmp[c] = L[i]; idx[c++] = i; } for (int a = 0; a < c; a++) for (int e = a + 1; e < c; e++) if (strcmp(tmp[a].t, tmp[e].t) > 0) { it_t t = tmp[a]; tmp[a] = tmp[e]; tmp[e] = t; int q = idx[a]; idx[a] = idx[e]; idx[e] = q; } for (int a = 0; a < c && a < 8; a++) { if (sel == idx[a]) g_rect(W, X, y, w, 22, UI_ACC2); g_text(W, X + 4, y + 3, tmp[a].t, UI_ACC); zw_clip(W, X + 52, y, w - 52, 22); g_text(W, X + 52, y + 3, tmp[a].txt, UI_TEXT); zw_noclip(W); vis[nv++] = idx[a]; y += 22; } y = 56 + 26 + 8 * 22 + 12; g_rect(W, X, y - 6, w, 1, UI_LINE); g_textb(W, X, y, "Tareas", UI_TEXT); ui_button(W, W->w - 96, y - 4, 84, 24, "+ Tarea", 0); y += 26; for (int i = 0; i < n && nv < 24 && y < W->h - 44; i++) if (!L[i].y) { if (sel == i) g_rect(W, X, y, w, 22, UI_ACC2); g_frame(W, X + 3, y + 5, 12, 12, UI_MUTED); if (L[i].done) g_rect(W, X + 5, y + 7, 8, 8, UI_ACC); zw_clip(W, X + 22, y, w - 22, 22); g_text(W, X + 22, y + 3, L[i].txt, L[i].done ? UI_MUTED : UI_TEXT); zw_noclip(W); vis[nv++] = i; y += 22; } ui_button(W, W->w - 96, W->h - 34, 84, 26, "Borrar", sel >= 0 ? 2 : 0); zs_stop(W); zs_show(W); zw_present(W);
}
/* Imprimir: las citas del mes mostrado y las tareas pendientes */
static void print_(void) { sb_t b = {0}; sb_s(&b, ""); char t[200]; int any = 0; it_t *v = malloc(n * sizeof *v + 1); int k = 0; for (int i = 0; i < n; i++) if (L[i].y == Y && L[i].m == M) v[k++] = L[i];
    for (int i = 0; i < k; i++) for (int j = i + 1; j < k; j++) if (v[j].d < v[i].d || (v[j].d == v[i].d && strcmp(v[j].t, v[i].t) < 0)) { it_t x = v[i]; v[i] = v[j]; v[j] = x; }
    int last = 0; for (int i = 0; i < k; i++) { if (v[i].d != last) { last = v[i].d; static const char *DW[] = {"Lunes", "Martes", "Miércoles", "Jueves", "Viernes", "Sábado", "Domingo"}; if (TH.lang) snprintf(t, 200, "%s%s, %s %d", any ? "\n" : "", _(DW[dow(Y, M, last)]), _(MN[M - 1]), last); else snprintf(t, 200, "%s%s %d de %s", any ? "\n" : "", DW[dow(Y, M, last)], last, MN[M - 1]); sb_s(&b, t); sb_s(&b, "\n"); } snprintf(t, 200, "   %s   %s\n", v[i].t, v[i].txt); sb_s(&b, t); any = 1; }
    if (!any) { sb_s(&b, _("No hay citas este mes.")); sb_s(&b, "\n"); } int tk = 0; for (int i = 0; i < n; i++) if (!L[i].y) { if (!tk++) { sb_s(&b, "\n"); sb_s(&b, _("Tareas")); sb_s(&b, "\n"); } snprintf(t, 200, "   [%s]  %s\n", L[i].done ? "x" : "  ", L[i].txt); sb_s(&b, t); }
    char ti[80]; snprintf(ti, 80, "%s - %s %d", _("Agenda"), _(MN[M - 1]), Y); zp_print_text(ti, 0, b.p, 0); free(b.p); free(v); }
static void month(int d) { M += d; if (M < 1) { M = 12; Y--; } if (M > 12) { M = 1; Y++; } D = MIN(D, dim(Y, M)); sel = -1; }
int main(const char *a) { char dd[120]; z_docdir(dd); snprintf(file, 200, "%s/AGENDA.TXT", dd); L = malloc(2000 * sizeof *L); load(); u32 t[6]; z_time(t); tY = Y = t[5]; tM = M = t[4]; tD = D = t[3]; W = zw_new("Agenda", -1, 0, 800, 460, WF_DECOR); draw(); zevent e;
    for (;;) { if (!z_event(&e, -1) || e.win != (u32)W->id) continue; if (e.type == EV_REDRAW) { draw(); continue; } if (zs_event(W, &e)) { draw(); continue; } if (e.type == EV_CLOSE) return 0; if (e.type == EV_KEY && e.ch == 16) { print_(); draw(); continue; } if (e.type == EV_DOWN && e.y < 44 && e.x >= W->w - 110) { print_(); draw(); continue; } if (e.type == EV_KEY) { if (e.key == K_LEFT) D > 1 ? D-- : (month(-1), D = dim(Y, M)); else if (e.key == K_RIGHT) D < dim(Y, M) ? D++ : (month(1), D = 1); else if (e.key == K_UP) D = MAX(1, D - 7); else if (e.key == K_DOWN) D = MIN(dim(Y, M), D + 7); else if (e.key == K_DEL && sel >= 0) goto del; draw(); continue; } if (e.type != EV_DOWN) continue; int X = CX + 7 * CW + 16; if (e.y < 44) { if (e.x < 48) month(-1); else if (e.x < 86) month(1); else if (e.x < 152) { Y = tY; M = tM; D = tD; } }
        else if (e.x < X - 8) { int c = (e.x - CX) / CW, r = (e.y - CY - 12) / CH, d = r * 7 + c - dow(Y, M, 1) + 1; if (e.y >= CY + 12 && c >= 0 && c < 7 && d >= 1 && d <= dim(Y, M)) { D = d; sel = -1; } }
        else if (e.x >= W->w - 96 && e.y >= 52 && e.y < 76) { char t2[120] = "", h[8] = "09:00"; if (ui_prompt("Nueva cita", "Hora (HH:MM):", h, 6) && ui_prompt("Nueva cita", "Descripcion:", t2, 110) && t2[0] && n < 2000) { it_t *i = &L[n++]; memset(i, 0, sizeof *i); i->y = Y; i->m = M; i->d = D; strncpy0(i->t, h, 6); strcpy(i->txt, t2); save(); } }
        else if (e.x >= W->w - 96 && e.y >= 56 + 26 + 176 + 8 && e.y < 56 + 26 + 176 + 12 + 22) { char t2[120] = ""; if (ui_prompt("Nueva tarea", "Tarea:", t2, 110) && t2[0] && n < 2000) { it_t *i = &L[n++]; memset(i, 0, sizeof *i); strcpy(i->txt, t2); save(); } }
        else if (e.x >= W->w - 96 && e.y >= W->h - 34 && sel >= 0) { del: memmove(&L[sel], &L[sel + 1], (n - sel - 1) * sizeof *L); n--; sel = -1; save(); }
        else { int y0 = 82, cnt = 0; for (int i = 0; i < n; i++) if (L[i].y == Y && L[i].m == M && L[i].d == D) cnt++; cnt = MIN(cnt, 8); if (e.y >= y0 && e.y < y0 + cnt * 22) sel = vis[(e.y - y0) / 22]; else { int ty = 82 + 176 + 12 + 26; if (e.y >= ty) { int k = cnt + (e.y - ty) / 22; if (k < nv) { sel = vis[k]; if (e.x < X + 18 && !L[sel].y) { L[sel].done ^= 1; save(); } } } } } draw(); }
}
